<h1><?= te('Email delivery') ?></h1><p class="sub"><?= te('Automatic activation invitations are encrypted in the queue. An approved mail relay and scheduled delivery worker are required.') ?></p>
<div class="card scroll"><table><tr><th><?= te('Recipient') ?></th><th><?= te('Queue status') ?></th><th><?= te('Attempts') ?></th><th><?= te('Created') ?></th><th><?= te('Action') ?></th></tr><?php foreach($messages as $message): ?><tr><td><?= e($message['recipient']) ?></td><td><?= e($message['status']) ?></td><td><?= (int)$message['attempts'] ?></td><td><?= e($message['created_at']) ?></td><td><?php if($message['status']==='failed' && $message['attempts']<5): ?><form method="post"><?= csrf_field() ?><input name="id" type="hidden" value="<?= (int)$message['id'] ?>"><button class="btn ghost sm"><?= te('Retry') ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></table></div>
